# 解决控制台输出堆积问题并实现自动滚动

对于大量控制台输出导致的内存和性能问题，以及实现自动滚动效果，你可以采用以下几种解决方案：

## 方案1：限制文本区域内容长度 + 自动滚动

```java
import javax.swing.*;
import javax.swing.text.*;
import java.awt.*;
import java.io.*;

public class LimitedConsoleOutput {
    private static final int MAX_LINES = 1000; // 最大保留行数
    private static final int LINE_LENGTH = 200; // 每行最大长度

    public static void main(String[] args) {
        JFrame frame = new JFrame("有限控制台输出");
        JTextPane textPane = new JTextPane();
        textPane.setEditable(false);
        JScrollPane scrollPane = new JScrollPane(textPane);

        // 创建文档并设置限制
        LimitedStyledDocument doc = new LimitedStyledDocument(MAX_LINES);
        textPane.setDocument(doc);

        // 重定向输出
        System.setOut(new PrintStream(new TextPaneOutputStream(doc, createStyle(doc, Color.BLACK)), true));
        System.setErr(new PrintStream(new TextPaneOutputStream(doc, createStyle(doc, Color.RED)), true));

        frame.add(scrollPane);
        frame.pack();
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setVisible(true);

        // 测试输出
        new Thread(() -> {
            for (int i = 0; i < 5000; i++) {
                System.out.println("这是一条测试消息 " + i);
                try { Thread.sleep(10); } catch (InterruptedException e) {}
            }
        }).start();
    }

    private static Style createStyle(StyledDocument doc, Color color) {
        Style style = doc.addStyle(color.toString(), null);
        StyleConstants.setForeground(style, color);
        return style;
    }
}

class LimitedStyledDocument extends DefaultStyledDocument {
    private final int maxLines;
    private int currentLines = 0;

    public LimitedStyledDocument(int maxLines) {
        this.maxLines = maxLines;
    }

    @Override
    public void insertString(int offs, String str, AttributeSet a) throws BadLocationException {
        // 限制行数
        if (currentLines >= maxLines) {
            int endOfFirstLine = getText(0, getLength()).indexOf("\n");
            if (endOfFirstLine != -1) {
                remove(0, endOfFirstLine + 1);
                currentLines--;
            }
        }

        super.insertString(offs, str, a);

        // 计算新增的行数
        long newLineCount = str.chars().filter(ch -> ch == '\n').count();
        currentLines += newLineCount;
    }
}

class TextPaneOutputStream extends OutputStream {
    private final StyledDocument doc;
    private final Style style;
    private final JTextPane textPane;

    public TextPaneOutputStream(StyledDocument doc, Style style) {
        this.doc = doc;
        this.style = style;
        this.textPane = (JTextPane) doc.getProperty("textPane");
    }

    @Override
    public void write(int b) throws IOException {
        write(new byte[]{(byte)b}, 0, 1);
    }

    @Override
    public void write(byte[] b, int off, int len) throws IOException {
        final String text = new String(b, off, len);
        SwingUtilities.invokeLater(() -> {
            try {
                // 追加文本
                doc.insertString(doc.getLength(), text, style);

                // 自动滚动到底部
                textPane.setCaretPosition(doc.getLength());
            } catch (BadLocationException e) {
                e.printStackTrace();
            }
        });
    }
}
```

## 方案2：环形缓冲区实现（更高效的内存管理）

```java
import javax.swing.*;
import javax.swing.text.*;
import java.io.*;
import java.util.LinkedList;

public class CircularBufferConsole {
    private static final int BUFFER_SIZE = 1000; // 保留的行数

    public static void main(String[] args) {
        JFrame frame = new JFrame("环形缓冲区控制台");
        JTextArea textArea = new JTextArea(20, 50);
        textArea.setEditable(false);
        JScrollPane scrollPane = new JScrollPane(textArea);

        // 创建环形缓冲区输出流
        CircularBufferOutputStream outputStream = new CircularBufferOutputStream(textArea, BUFFER_SIZE);
        PrintStream printStream = new PrintStream(outputStream, true);

        System.setOut(printStream);
        System.setErr(printStream);

        frame.add(scrollPane);
        frame.pack();
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setVisible(true);

        // 测试输出
        new Thread(() -> {
            for (int i = 0; i < 5000; i++) {
                System.out.println("测试消息 " + i + " " + new java.util.Date());
                try { Thread.sleep(10); } catch (InterruptedException e) {}
            }
        }).start();
    }
}

class CircularBufferOutputStream extends OutputStream {
    private final JTextArea textArea;
    private final int bufferSize;
    private final LinkedList<String> buffer = new LinkedList<>();
    private StringBuilder currentLine = new StringBuilder();

    public CircularBufferOutputStream(JTextArea textArea, int bufferSize) {
        this.textArea = textArea;
        this.bufferSize = bufferSize;
    }

    @Override
    public void write(int b) throws IOException {
        if (b == '\n') {
            flushLine();
        } else {
            currentLine.append((char)b);
        }
    }

    private void flushLine() {
        String line = currentLine.toString();
        currentLine = new StringBuilder();

        synchronized (buffer) {
            if (buffer.size() >= bufferSize) {
                buffer.removeFirst();
            }
            buffer.add(line);
        }

        updateTextArea();
    }

    private void updateTextArea() {
        SwingUtilities.invokeLater(() -> {
            StringBuilder content = new StringBuilder();
            synchronized (buffer) {
                for (String line : buffer) {
                    content.append(line).append("\n");
                }
            }
            textArea.setText(content.toString());
            textArea.setCaretPosition(textArea.getDocument().getLength());
        });
    }

    @Override
    public void flush() throws IOException {
        if (currentLine.length() > 0) {
            flushLine();
        }
    }
}
```

## 方案3：分页显示（适合极大量输出）

```java
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;

public class PagedConsoleOutput {
    private static final int PAGE_SIZE = 500; // 每页行数
    private static int currentPage = 0;
    private static java.util.List<String> allLines = new java.util.ArrayList<>();

    public static void main(String[] args) {
        JFrame frame = new JFrame("分页控制台输出");
        JTextArea textArea = new JTextArea(20, 50);
        textArea.setEditable(false);
        JScrollPane scrollPane = new JScrollPane(textArea);

        JPanel controlPanel = new JPanel();
        JButton prevButton = new JButton("上一页");
        JButton nextButton = new JButton("下一页");
        JLabel pageLabel = new JLabel("第0页");

        controlPanel.add(prevButton);
        controlPanel.add(pageLabel);
        controlPanel.add(nextButton);

        frame.add(scrollPane, BorderLayout.CENTER);
        frame.add(controlPanel, BorderLayout.SOUTH);

        // 重定向输出
        System.setOut(new PrintStream(new TextAreaPagedOutputStream(allLines, textArea, pageLabel)));

        // 按钮事件
        prevButton.addActionListener(e -> {
            if (currentPage > 0) {
                currentPage--;
                updateDisplay();
            }
        });

        nextButton.addActionListener(e -> {
            if ((currentPage + 1) * PAGE_SIZE < allLines.size()) {
                currentPage++;
                updateDisplay();
            }
        });

        frame.pack();
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setVisible(true);

        // 测试输出
        new Thread(() -> {
            for (int i = 0; i < 5000; i++) {
                System.out.println("测试消息 " + i + " " + new java.util.Date());
                try { Thread.sleep(10); } catch (InterruptedException e) {}
            }
        }).start();
    }

    private static void updateDisplay() {
        SwingUtilities.invokeLater(() -> {
            StringBuilder sb = new StringBuilder();
            int start = currentPage * PAGE_SIZE;
            int end = Math.min(start + PAGE_SIZE, allLines.size());

            for (int i = start; i < end; i++) {
                sb.append(allLines.get(i)).append("\n");
            }

            ((JLabel)((JPanel)((JFrame)SwingUtilities.getWindowAncestor(
                ((JViewport)((JScrollPane)SwingUtilities.getAncestorOfClass(
                    JScrollPane.class, 
                    SwingUtilities.getWindowAncestor(sb)
                ))).getViewport().getView()
            )).getComponent(0))).setText("第" + currentPage + "页");

            ((JTextArea)((JViewport)((JScrollPane)SwingUtilities.getAncestorOfClass(
                JScrollPane.class, 
                SwingUtilities.getWindowAncestor(sb)
            ))).getViewport().getView()).setText(sb.toString());
        });
    }
}

class TextAreaPagedOutputStream extends OutputStream {
    private final java.util.List<String> allLines;
    private final JTextArea textArea;
    private final JLabel pageLabel;
    private StringBuilder currentLine = new StringBuilder();

    public TextAreaPagedOutputStream(java.util.List<String> allLines, JTextArea textArea, JLabel pageLabel) {
        this.allLines = allLines;
        this.textArea = textArea;
        this.pageLabel = pageLabel;
    }

    @Override
    public void write(int b) throws IOException {
        if (b == '\n') {
            String line = currentLine.toString();
            currentLine = new StringBuilder();

            synchronized (allLines) {
                allLines.add(line);
            }

            updateDisplay();
        } else {
            currentLine.append((char)b);
        }
    }

    private void updateDisplay() {
        SwingUtilities.invokeLater(() -> {
            int currentPage = (allLines.size() - 1) / PagedConsoleOutput.PAGE_SIZE;
            pageLabel.setText("第" + currentPage + "页");

            StringBuilder sb = new StringBuilder();
            int start = currentPage * PagedConsoleOutput.PAGE_SIZE;
            int end = Math.min(start + PagedConsoleOutput.PAGE_SIZE, allLines.size());

            synchronized (allLines) {
                for (int i = start; i < end; i++) {
                    sb.append(allLines.get(i)).append("\n");
                }
            }

            textArea.setText(sb.toString());
            textArea.setCaretPosition(textArea.getDocument().getLength());
        });
    }
}
```

## 最佳实践建议

1. **对于普通应用**：使用方案1（限制行数）+自动滚动，这是最平衡的方案
   - 设置合理的最大行数（如1000-5000行）
   - 确保自动滚动到底部

2. **对于高性能需求**：使用方案2的环形缓冲区
   - 内存占用更稳定
   - 避免频繁的字符串操作

3. **对于极大量日志**：使用方案3的分页显示
   - 适合需要查看历史日志的场景
   - 可以添加搜索功能增强实用性

4. **额外优化**：
   ```java
   // 在初始化文本组件时设置这些属性可以提高性能
   textArea.setLineWrap(true);
   textArea.setWrapStyleWord(true);
   textArea.setAutoscrolls(true);

   // 对于大量文本，关闭不必要的监听器
   textArea.getDocument().putProperty("filterNewlines", Boolean.TRUE);
   ```

5. **内存监控**：
   ```java
   // 添加一个内存监控按钮
   JButton memButton = new JButton("内存状态");
   memButton.addActionListener(e -> {
       Runtime rt = Runtime.getRuntime();
       long total = rt.totalMemory();
       long free = rt.freeMemory();
       long used = total - free;
       System.out.printf("内存使用: %,d / %,d MB (%.1f%%)%n",
           used / (1024 * 1024),
           total / (1024 * 1024),
           (used * 100.0 / total));
   });
   ```

选择哪种方案取决于你的具体需求，但方案1通常是大多数情况下的最佳选择。
